window.addEventListener('load', () => {
    GDIUserSystem.init();
    PomodoroSystem.init();
    
    const theme = StorageManager.get('theme') || 'dark';
    applyTheme(theme);
    
    if ('Notification' in window && Notification.permission === 'default') {
        Notification.requestPermission();
    }
});

