function fileVideo(name, size, streamUrl, poster, mimeType, fileId) {
    const UI = window.UI || {};
    const playerConfig = window.player_config || {};
    
    const notesPanel = `
    <div id="gdi-notes-panel" style="display:none;margin-top:16px;background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.1);border-radius:8px;padding:16px;">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;">
            <strong><i class="bi bi-journal-text me-2"></i>Anotações da Aula</strong>
            <button onclick="toggleNotesPanel()" style="background:none;border:none;color:#8b949e;font-size:20px;cursor:pointer;">&times;</button>
        </div>
        <div id="gdi-notes-list" style="max-height:200px;overflow-y:auto;margin-bottom:12px;"></div>
        <div style="display:flex;gap:8px;">
            <input id="gdi-note-input" type="text" placeholder="Adicionar nota..." 
                   style="flex:1;background:rgba(255,255,255,0.1);border:1px solid rgba(255,255,255,0.2);border-radius:4px;padding:6px 10px;color:#e6edf3;"
                   onkeypress="if(event.key==='Enter')addVideoNote()">
            <button class="btn btn-sm btn-primary" onclick="addVideoNote()"><i class="bi bi-plus"></i></button>
        </div>
    </div>`;
    
    const playerHtml = playerConfig.player === "plyr" ? 
        `<video id="player" playsinline controls autoplay muted data-poster="${poster}"><source src="${streamUrl}" type="video/mp4"></video>` :
        playerConfig.player === "videojs" ?
        `<video id="vplayer" poster="${poster}" class="video-js vjs-default-skin vjs-big-play-centered" controls autoplay width="100%" height="100%"><source src="${streamUrl}" type="video/mp4"></video>` :
        `<video id="player" controls autoplay style="width:100%;height:auto;border-radius:8px;background:#000;" poster="${poster}"><source src="${streamUrl}" type="video/mp4"></video>`;
    
    const content = `
    <div style="padding:20px;max-width:1200px;margin:0 auto;">
        <div style="margin-bottom:24px;">
            <h1 style="font-size:24px;color:#e6edf3;margin-bottom:8px;">${escHtml(name)}</h1>
            <div style="font-size:14px;color:#8b949e;">${size}</div>
        </div>
        
        <div style="background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.1);border-radius:12px;overflow:hidden;margin-bottom:20px;">
            <div style="aspect-ratio:16/9;background:#000;">${playerHtml}</div>
        </div>
        
        <div style="display:flex;gap:8px;margin-bottom:20px;">
            <button class="btn btn-primary" onclick="toggleNotesPanel()"><i class="bi bi-journal-text me-2"></i>Anotações</button>
            <button class="btn btn-secondary" onclick="downloadFile('${streamUrl}', '${name}')"><i class="bi bi-download me-2"></i>Download</button>
        </div>
        
        ${notesPanel}
    </div>`;
    
    $("#content").html(content);
    setupVideoProgressTracking(fileId, name, window.location.href);
    
    // Carregar player
    if (playerConfig.player === "plyr" && !window.Plyr) {
        const script = document.createElement("script");
        script.src = "https://cdn.plyr.io/3.7.8/plyr.polyfilled.js";
        document.head.appendChild(script);
        script.onload = () => initPlyrPlayer(name);
    } else if (playerConfig.player === "plyr") {
        initPlyrPlayer(name);
    }
}

function initPlyrPlayer(videoName) {
    const player = new Plyr("#player", {autoplay: true, keyboard: {global: true}});
    window._gdiPlayerInstance = player;
    
    player.on("ready", () => {
        player.play().catch(() => {});
        setTimeout(() => player.muted = false, 2000);
    });
    
    player.on("play", () => updateVideoProgress());
    player.on("pause", () => updateVideoProgress());
    player.on("seeked", () => updateVideoProgress());
    player.on("ended", () => {
        GDIUserSystem.saveVideoProgress(getCurrentVideoId(), {
            name: videoName,
            currentTime: player.currentTime,
            duration: player.duration,
            url: window.location.href
        });
    });
}

